package dashboard

import (
	"bytes"
	"fmt"
	"os"
	"path"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

// messagesDirName is the per-system directory holding authored message
// descriptions: one Markdown file per port, named after it
// (messages/<port>.md), with YAML frontmatter for the structured facts
// and free prose in the body.
const messagesDirName = "messages"

// maxMessageBodyBytes caps the prose body served for one message description.
const maxMessageBodyBytes = 16 * 1024

// messageDoc is an authored description of the payload a port carries —
// the flat file from an SFTP drop, the ad-hoc CSV export — written by a
// developer because no machine spec exists. It is documentation, not
// enforcement: the runtime never validates against it. Contact and
// LastReviewed are its staleness story.
type messageDoc struct {
	Format       string     `json:"format,omitempty" yaml:"format"`
	Delimiter    string     `json:"delimiter,omitempty" yaml:"delimiter"`
	Encoding     string     `json:"encoding,omitempty" yaml:"encoding"`
	FilePattern  string     `json:"filePattern,omitempty" yaml:"filePattern"`
	Frequency    string     `json:"frequency,omitempty" yaml:"frequency"`
	Contact      string     `json:"contact,omitempty" yaml:"contact"`
	LastReviewed string     `json:"lastReviewed,omitempty" yaml:"lastReviewed"`
	Fields       []docField `json:"fields,omitempty" yaml:"fields"`
	Sample       *docSample `json:"sample,omitempty" yaml:"sample"`
	Body         string     `json:"body,omitempty" yaml:"-"`
}

// docField describes one field or column of an external payload. Type is
// loose by design (string/integer/decimal/date/boolean/other) — it records
// what the author knows, not a validatable schema.
type docField struct {
	Name     string `json:"name" yaml:"name"`
	Position int    `json:"position,omitempty" yaml:"position"`
	Type     string `json:"type,omitempty" yaml:"type"`
	Required bool   `json:"required,omitempty" yaml:"required"`
	Notes    string `json:"notes,omitempty" yaml:"notes"`
}

// docSample is a short inline payload excerpt. Redacted is a pointer so an
// author cannot publish a sample without explicitly asserting they considered
// what it exposes — an absent value rejects the sample, not defaults it.
type docSample struct {
	Inline   string `json:"inline" yaml:"inline"`
	Redacted *bool  `json:"redacted" yaml:"redacted"`
}

// readMessageDocs collects the authored message descriptions under a system
// directory, keyed by port name (the filename). Problems are returned as
// strings for the report's error banner — a broken doc never fails the
// request, and error paths are relative to dir so callers can prefix the
// system's identifier.
func readMessageDocs(dir string) (map[string]messageDoc, []string) {
	ents, err := os.ReadDir(filepath.Join(dir, messagesDirName))
	if err != nil {
		return nil, nil
	}
	var docs map[string]messageDoc
	var errs []string
	for _, ent := range ents {
		if ent.IsDir() || !strings.HasSuffix(ent.Name(), ".md") {
			continue
		}
		rel := path.Join(messagesDirName, ent.Name())
		data, err := os.ReadFile(filepath.Join(dir, messagesDirName, ent.Name()))
		if err != nil {
			errs = append(errs, fmt.Sprintf("%s: %v", rel, err))
			continue
		}
		doc, docErrs := parseMessageDoc(data)
		for _, e := range docErrs {
			errs = append(errs, fmt.Sprintf("%s: %s", rel, e))
		}
		if doc == nil {
			continue
		}
		if docs == nil {
			docs = map[string]messageDoc{}
		}
		docs[strings.TrimSuffix(ent.Name(), ".md")] = *doc
	}
	return docs, errs
}

// parseMessageDoc splits a doc into YAML frontmatter and prose body. A file
// without frontmatter is a valid prose-only description. A doc is only
// rejected (nil) when its frontmatter does not parse; lesser problems drop
// the offending part and report it.
func parseMessageDoc(data []byte) (*messageDoc, []string) {
	meta, body := splitFrontmatter(data)
	var doc messageDoc
	if len(meta) > 0 {
		if err := yaml.Unmarshal(meta, &doc); err != nil {
			return nil, []string{fmt.Sprintf("invalid frontmatter: %v", err)}
		}
	}
	var errs []string
	if doc.Sample != nil && doc.Sample.Redacted == nil {
		doc.Sample = nil
		errs = append(errs, "sample dropped: set redacted: true|false to assert the sample was checked for sensitive data")
	}
	if len(body) > maxMessageBodyBytes {
		body = body[:maxMessageBodyBytes]
	}
	doc.Body = strings.TrimSpace(string(body))
	return &doc, errs
}

// splitFrontmatter separates a leading YAML frontmatter block (delimited by
// "---" lines) from the document body. Without an opening delimiter on the
// first line the whole input is body.
func splitFrontmatter(data []byte) (meta, body []byte) {
	normalized := bytes.ReplaceAll(data, []byte("\r\n"), []byte("\n"))
	rest, ok := bytes.CutPrefix(normalized, []byte("---\n"))
	if !ok {
		return nil, normalized
	}
	if meta, body, ok = bytes.Cut(rest, []byte("\n---\n")); ok {
		return meta, body
	}
	// Closing delimiter at end-of-file without a trailing newline.
	if meta, ok = bytes.CutSuffix(rest, []byte("\n---")); ok {
		return meta, nil
	}
	// No closing delimiter: not frontmatter after all.
	return nil, normalized
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  api,
  type CreateResponse,
  type TemplateDetail,
  type TemplateList,
  type TemplateSummary,
} from '../api'
import { Combobox } from './Combobox'
import { Field, FormField, isEmpty } from './form'

/** The three create placeholders on the flow canvas, one per archetype
 *  column: in → process → out. */
export type SlotKind = 'extractor' | 'transactional' | 'loader'

// The intropy.dev/block-kind label value each slot filters templates by.
const KIND_BLOCK_LABEL: Record<SlotKind, string> = {
  extractor: 'extractor',
  transactional: 'transactional-integration',
  loader: 'loader',
}

const KIND_TITLE: Record<SlotKind, string> = {
  extractor: 'extractor',
  transactional: 'core block',
  loader: 'loader',
}

type CreateState =
  | { phase: 'idle' }
  | { phase: 'running' }
  | { phase: 'error'; message: string; status: number }

// norm compares label values the way dataFlowFor compares kinds: ignoring
// case and hyphens, so "transactional-integration" matches however the
// library spells it.
const norm = (s: string) => s.toLowerCase().replace(/-/g, '')

interface Props {
  kind: SlotKind
  /** Root-relative directory the new block scaffolds into ("." = workspace root). */
  systemPath: string
  systemLabel: string
  onClose: () => void
  /** Called with the created scaffold's root-relative path — the caller
   *  refreshes /api/flow so the new block appears as a ghost node. */
  onCreated: (outputDir: string) => void
}

// CreateDrawer is the flow view's create surface: opened by a placeholder
// slot, it offers the library's templates for that block kind and renders the
// selected one's manifest as the same form the templates view uses, scoped to
// the slot's system. Success is reported to the caller — the drawer closes
// and the canvas shows the new scaffold as a ghost node.
export function CreateDrawer({ kind, systemPath, systemLabel, onClose, onCreated }: Props) {
  const [list, setList] = useState<TemplateList | null>(null)
  const [listError, setListError] = useState<string | null>(null)
  const [showAll, setShowAll] = useState(false)
  const [tpl, setTpl] = useState<string | null>(null)

  useEffect(() => {
    api
      .listTemplates()
      .then(setList)
      .catch((e: unknown) => setListError(errText(e)))
  }, [])

  const candidates = useMemo<TemplateSummary[]>(() => {
    if (!list) return []
    const entries: TemplateSummary[] =
      list.entries ?? list.templates.map((name) => ({ name }))
    if (showAll) return entries
    const want = norm(KIND_BLOCK_LABEL[kind])
    return entries.filter((e) => norm(e.labels?.['intropy.dev/block-kind'] ?? '') === want)
  }, [list, showAll, kind])

  // Keep the selection valid as the candidate list settles (load, show-all).
  useEffect(() => {
    setTpl((cur) =>
      cur && candidates.some((c) => c.name === cur) ? cur : candidates[0]?.name ?? null,
    )
  }, [candidates])

  return (
    <aside className="create-drawer">
      <header className="create-drawer-head">
        <div>
          <h2 className="create-drawer-title">New {KIND_TITLE[kind]}</h2>
          <span className="create-drawer-sys">in {systemLabel}</span>
        </div>
        <button type="button" className="flow-detail-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </header>

      {listError && <div className="banner error">{listError}</div>}
      {!list && !listError && <div className="empty">loading templates…</div>}

      {list && candidates.length === 0 && (
        <div className="empty">
          no template in {list.owner}/{list.repo}@{list.version} carries{' '}
          <code>intropy.dev/block-kind: {KIND_BLOCK_LABEL[kind]}</code>
          <div>
            <button type="button" className="flow-refresh" onClick={() => setShowAll(true)}>
              show all templates
            </button>
          </div>
        </div>
      )}

      {list && candidates.length > 0 && (
        <>
          <Field label="template" required>
            <Combobox
              value={tpl}
              options={candidates.map((c) => ({
                value: c.name,
                label: c.title ? `${c.title} (${c.name})` : c.name,
              }))}
              onChange={setTpl}
              placeholder="Select a template…"
            />
          </Field>
          {!showAll && (
            <button
              type="button"
              className="drawer-show-all"
              onClick={() => setShowAll(true)}
            >
              show all templates
            </button>
          )}
          {tpl && (
            <DrawerForm
              key={tpl}
              template={tpl}
              systemPath={systemPath}
              onCreated={onCreated}
            />
          )}
        </>
      )}
    </aside>
  )
}

// DrawerForm mirrors the templates view's TemplatePanel: manifest fetched,
// defaults seeded, required fields tracked, force offered on a 409. It is
// keyed by template name so switching templates resets all form state. The
// differences: the output directory is locked under the slot's system, and
// success closes the drawer instead of rendering a result card.
function DrawerForm({
  template,
  systemPath,
  onCreated,
}: {
  template: string
  systemPath: string
  onCreated: Props['onCreated']
}) {
  const [detail, setDetail] = useState<TemplateDetail | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [values, setValues] = useState<Record<string, unknown>>({})
  const [intName, setIntName] = useState('')
  const [force, setForce] = useState(false)
  const [create, setCreate] = useState<CreateState>({ phase: 'idle' })

  useEffect(() => {
    api
      .getTemplate(template)
      .then((d) => {
        setDetail(d)
        // Prefill declared defaults so the form shows what a bare run would use.
        const seeded: Record<string, unknown> = {}
        for (const f of d.fields) {
          if (f.default !== undefined) seeded[f.name] = f.default
        }
        setValues(seeded)
      })
      .catch((e: unknown) => setError(errText(e)))
  }, [template])

  const setValue = useCallback((key: string, v: unknown) => {
    setValues((prev) => ({ ...prev, [key]: v }))
  }, [])

  const missing = useMemo(() => {
    if (!detail) return []
    return detail.fields
      .filter((f) => f.required && isEmpty(values[f.name]))
      .map((f) => f.name)
  }, [detail, values])

  const run = useCallback(() => {
    setCreate({ phase: 'running' })
    api
      .createTemplate(template, { name: intName, dir: systemPath, values, force })
      .then((result: CreateResponse) => onCreated(result.outputDir))
      .catch((e: unknown) => {
        const err = e as { message?: string; status?: number }
        setCreate({ phase: 'error', message: errText(e), status: err.status ?? 0 })
      })
  }, [template, intName, systemPath, values, force, onCreated])

  if (error) {
    return <div className="banner error">{error}</div>
  }
  if (!detail) {
    return <div className="empty">loading {template}…</div>
  }

  const canRun = intName.trim() !== '' && missing.length === 0 && create.phase !== 'running'
  const prefix = systemPath === '.' ? '' : `${systemPath}/`

  return (
    <form
      className="template-form"
      onSubmit={(e) => {
        e.preventDefault()
        if (canRun) run()
      }}
    >
      {detail.description && <p className="template-desc">{detail.description}</p>}

      <Field
        label="out-dir"
        title="Output directory"
        description={
          prefix
            ? 'Scaffolded inside the system directory'
            : 'Scaffolded under the workspace root'
        }
        required
      >
        <div className="drawer-dir">
          {prefix && <span className="drawer-dir-prefix">{prefix}</span>}
          <input
            type="text"
            value={intName}
            onChange={(e) => setIntName(e.target.value)}
            placeholder="my-integration"
            autoFocus
