/// <summary>
/// The kind of Dapr binding a connector materializes as. A transport names the binding
/// type and states what that binding can do; it deliberately carries no address, host,
/// or credential. Those differ per environment and stay in the deployment repository,
/// so the same declaration describes the connector in every environment.
/// </summary>
public sealed class Transport
{
    /// <summary>The Dapr binding component's <c>spec.type</c>, e.g. "bindings.sftp".</summary>
    public required string DaprType { get; set; }

    /// <summary>Whether the binding can read from the external system (an inbound connector).</summary>
    public required bool SupportsInput { get; set; }

    /// <summary>Whether the binding can write to the external system (an outbound connector).</summary>
    public required bool SupportsOutput { get; set; }

    /// <summary>File field: the folder the binding reads and writes.</summary>
    public string? RootPath { get; set; }

    /// <summary>An SFTP binding (<c>bindings.sftp</c>), which both reads and writes.</summary>
    public static Transport Sftp() =>
        new() { DaprType = "bindings.sftp", SupportsInput = true, SupportsOutput = true };

    /// <summary>An Azure Blob Storage binding (<c>bindings.azure.blobstorage</c>), which both reads and writes.</summary>
    public static Transport Blob() =>
        new() { DaprType = "bindings.azure.blobstorage", SupportsInput = true, SupportsOutput = true };

    /// <summary>
    /// An HTTP binding (<c>bindings.http</c>). Output only: Dapr invokes it, but it cannot
    /// trigger a component, so an HTTP connector can only be an outbound one.
    /// </summary>
    public static Transport Http() =>
        new() { DaprType = "bindings.http", SupportsInput = false, SupportsOutput = true };

    /// <summary>
    /// A local filesystem binding (<c>bindings.localstorage</c>) over <paramref name="rootPath"/>.
    /// The folder is the endpoint, so a file transport needs no external configuration — which is
    /// what makes it the default local stand-in for a deployed connector.
    /// </summary>
    public static Transport File(string rootPath) =>
        new()
        {
            DaprType = "bindings.localstorage",
            SupportsInput = true,
            SupportsOutput = true,
            RootPath = rootPath,
        };

    /// <summary>
    /// Any other Dapr binding type, with its capabilities stated explicitly because they
    /// cannot be inferred from the type name.
    /// </summary>
    public static Transport Custom(string daprType, bool supportsInput = true, bool supportsOutput = true) =>
        new() { DaprType = daprType, SupportsInput = supportsInput, SupportsOutput = supportsOutput };
}
